('90%_CUST_API'),('90%_CUSTNAME_API'),('BMW_Status_Report'),('Contract_Approval_Fetch'),('Contract_Approve_Reject'),('Create role'),('Create User'),('Create_User_Display_Table'),('Customer_Fetch_API'),('Edit_Role'),('Edit_User'),('Forgot_API'),('Gate_Pass_Doc_F4_API'),('Gate_Pass_Fetch_API'),('Gate_Pass_Save_API'),('Get_Plant'),('Get_Search_Term'),('GET_USER_PLANT'),('IMW_PMU_FETCH_API'),('IWM_PMU_EDIT_API'),('Login_API'),('Material_Fetch_API'),('Material_Save_API'),('MIGO_CANCEL'),('MIGO_Check_API'),('MIGO_Fetch_API'),('MIGO_POST_API'),('PMUA_APPROVE_API'),('PMUA_FETCH_API'),('PMUA_REJECT_API'),('PO_CANCEL_REJECT'),('PO_CANCEL_RELEASE'),('PO_GET_API'),('PO_REJECT_API'),('PO_Release_API'),('PR_CANCEL_REJECT'),('PR_CANCEL_RELEASE'),('PR_Reject_API'),('PR_Release_API'),('PR_Release_Multiple_Fetch_API'),('Price_Approval_Fetch'),('Price_Approve_Reject'),('Sales_Approval_Fetch'),('Sales_Order_Approve_Reject'),('Service_Certificate_Approve_Reject'),('SES_DELETE_API'),('SES_FETCH_API'),('SES_REJECT_API'),('SES_RELEASE_API'),('Sevice_Certificate_Fetch'),('ZGP_CANCEL_REPORT'),('ZGP_FETCH_REPORT'),('ZMC_Cancel_Report'),('ZMC_FETCH_REPORT'),('ZMIRS_DOC_F4_API'),('ZNFA_APPROVE_API'),('ZNFA_APPROVE_GET_API'),('ZNFA_ATTACH_API'),('ZNFA_ATTACH_PRINT_API'),('ZNFA_Clarification_API'),('ZNFA_Click _API'),('ZNFA_Create_API'),('ZNFA_DISPLAY_CLARIFY_API'),('ZNFA_DISPLAY_GET_API'),('ZNFA_Fetch_API'),('ZNFA_NFA_GET_API'),('ZNFA_PRINT_API'),('ZNFA_RATINGS_F4s_API'),('ZNFA_REJECT_API'),('ZNFA_RELEASE_GET_API'),('ZNFA_SAVE_API')
)
select e.name,
       case when c.id is null then 'MISSING' else 'INACTIVE' end as problem
from expected e
left join public.sap_api_configs c on c.name = e.name
where c.id is null or c.is_active is not true
order by 1;

